"""Reviewed benchmarks are external inputs, never generated by the teacher."""
from collections import Counter
from self_instruct_pipeline.config import resolve_path
from self_instruct_pipeline.persistence import read_jsonl, digest
from self_instruct_pipeline.deduplicator import Deduplicator
from self_instruct_pipeline.validation import validate_answer, validate_schema, check_hidden_fields


def load_benchmarks(config, schemas):
    settings = config.get('evaluation', {})
    if settings.get('mode') == 'fixed':
        if settings.get('holdout_families_per_task'):
            return fixed_family_split(config, schemas)
        return load_fixed_validation(config, schemas), []
    if settings.get('mode') in ('synthetic_smoke', 'automatic'):
        return None, []
    if settings.get('mode') != 'reviewed':
        raise ValueError('evaluation.mode must be fixed, reviewed, automatic, or synthetic_smoke')
    splits = []
    seen_ids, seen_sources = set(), set()
    dedup = Deduplicator([])
    for split, minimum in [('validation', config['development_examples_per_task']),
                           ('test', settings['minimum_test_examples_per_task'])]:
        path = resolve_path(settings[f'{split}_path'])
        if not path.is_file():
            raise ValueError(f'Missing reviewed {split} benchmark: {path}. See data/evaluation/README.md')
        rows = read_jsonl(path)
        counts = Counter()
        for item in rows:
            record = item['record']
            validate_schema(record, {'type': 'object', 'required': ['id', 'task', 'instruction', 'scenario'], 'properties': {
                'id': {'type': 'string', 'minLength': 1}, 'task': {'type': 'string'},
                'instruction': {'type': 'string', 'minLength': 1},
                'scenario': {'type': 'object', 'required': ['documents', 'context'], 'properties': {
                    'context': {'type': 'object'},
                    'documents': {'type': 'array', 'minItems': 1, 'items': {'type': 'object',
                        'required': ['document_id', 'page_number', 'text'], 'properties': {
                            'document_id': {'type': 'string', 'minLength': 1},
                            'page_number': {'type': 'integer', 'minimum': 1},
                            'text': {'type': 'string', 'minLength': 1}}}}}}}})
            check_hidden_fields(record['scenario']['context'])
            pages = [(d['document_id'], d['page_number']) for d in record['scenario']['documents']]
            if len(pages) != len(set(pages)):
                raise ValueError('Duplicate benchmark document/page pair')
            review = item.get('review', {})
            if any(not isinstance(review.get(k), str) or not review[k].strip() for k in ('reviewer', 'source_group')) or review.get('status') != 'approved':
                raise ValueError('Benchmark needs approved independent review and source_group')
            if record['task'] not in schemas:
                raise ValueError('Unknown benchmark task')
            validate_answer(record, item['reference'], schemas[record['task']])
            alternatives = item.get('accepted_references', [])
            if not isinstance(alternatives, list):
                raise ValueError('accepted_references must be an independently reviewed answer array')
            for alternative in alternatives:
                validate_answer(record, alternative, schemas[record['task']])
            if 'answer' in item['reference']:
                rubric = item.get('rubric', {})
                if (not isinstance(rubric, dict) or not isinstance(rubric.get('decision'), str)
                        or not rubric['decision'].strip() or not isinstance(rubric.get('required_facts'), list)
                        or not rubric['required_facts'] or any(not isinstance(x, str) or not x.strip() for x in rubric['required_facts'])):
                    raise ValueError('Reasoning benchmark requires reviewed rubric.decision and required_facts')
            if record['id'] in seen_ids or dedup.check(record):
                raise ValueError('Duplicate or overlapping benchmark scenario')
            seen_ids.add(record['id']); dedup.add(record)
            counts[record['task']] += 1
        groups = {item['review']['source_group'] for item in rows}
        sources = {digest(' '.join(page['text'].casefold().split()))
                   for item in rows for page in item['record']['scenario']['documents']}
        if (groups | sources) & seen_sources:
            raise ValueError('Validation and test source groups/documents overlap')
        seen_sources.update(groups | sources)
        if any(counts[t] < minimum for t in schemas):
            raise ValueError(f'Insufficient reviewed {split} task coverage; need {minimum} per task')
        splits.append(rows)
    return tuple(splits)


def comparison(baseline, selected):
    deltas = {task: selected['per_task'][task] - score for task, score in baseline['per_task'].items()}
    return {'baseline': baseline, 'selected': selected, 'per_task_delta': deltas,
            'regressed_tasks': [task for task, delta in deltas.items() if delta < 0],
            'macro_delta': selected['macro_task_score'] - baseline['macro_task_score']}


def load_fixed_validation(config, schemas):
    """Load only the shipped versioned corpus. Never call a teacher or repair it."""
    from .build_fixed_evaluation import VERSION
    from self_instruct_pipeline.deduplicator import fingerprint
    settings = config['evaluation']
    path = resolve_path(settings['validation_path'])
    manifest_path = resolve_path(settings['manifest_path'])
    if not path.is_file() or not manifest_path.is_file():
        raise ValueError('Missing bundled fixed evaluation data/manifest. Sync data/evaluation/fixed_validation_v1* from the repository. No API generation will be substituted.')
    rows = read_jsonl(path)
    import json
    manifest = json.loads(manifest_path.read_text())
    if (manifest.get('version') != VERSION or manifest.get('sha256') != digest(rows)
            or manifest.get('schema_hash') != digest(schemas)):
        raise ValueError('Fixed evaluation data, schema, or manifest hash has changed')
    counts = Counter(item['record']['task'] for item in rows)
    minimum = config['development_examples_per_task']
    if (set(counts) != set(schemas) or any(counts[t] < minimum for t in schemas)
            or len(rows) != manifest.get('total_examples')
            or dict(counts) != manifest.get('examples_per_task')):
        raise ValueError('Fixed evaluation task coverage disagrees with config/manifest')
    if len({item['record']['id'] for item in rows}) != len(rows) or len({fingerprint(item['record']) for item in rows}) != len(rows):
        raise ValueError('Duplicate fixed evaluation cases')
    for item in rows:
        record = item['record']
        if item.get('verification', {}).get('status') != 'locally_checked_synthetic' or item['verification'].get('human_reviewed') is not False:
            raise ValueError('Fixed evaluation provenance must remain locally checked synthetic')
        if 'review' in item:
            raise ValueError('Bundled synthetic evaluation is not independently reviewed gold')
        check_hidden_fields(record['scenario']['context'])
        validate_answer(record, item['reference'], schemas[record['task']])
    # The complete file is verified above even when evaluating a smaller subset.
    if 'total_examples' in settings:
        return fixed_subset(rows, schemas, settings['total_examples'], minimum,
                            settings.get('subset_seed', config['random_seed']))
    selected = []; used = Counter()
    for item in rows:
        task = item['record']['task']
        if used[task] < minimum:
            selected.append(item); used[task] += 1
    return selected


def fixed_subset(rows, tasks, total, minimum, seed):
    """Stable balanced task quotas with distinct reasoning families first."""
    import random
    if type(total) is not int or total < minimum * len(tasks) or total > len(rows):
        raise ValueError('Fixed subset total must fit the corpus and minimum task coverage')
    if type(seed) is not int or seed < 0:
        raise ValueError('Fixed subset seed must be a nonnegative integer')
    rng = random.Random(seed)
    task_order = sorted(tasks); rng.shuffle(task_order)
    quotas = {task: total // len(task_order) + int(i < total % len(task_order))
              for i, task in enumerate(task_order)}
    selected = []
    for task in sorted(tasks):
        families = {}
        for item in rows:
            if item['record']['task'] == task:
                families.setdefault(item['verification']['family'], []).append(item)
        family_order = sorted(families); rng.shuffle(family_order)
        for items in families.values(): rng.shuffle(items)
        ordered = []
        while any(families.values()):
            for family in family_order:
                if families[family]: ordered.append(families[family].pop())
        if len(ordered) < quotas[task]:
            raise ValueError('Requested fixed subset exceeds a task supply')
        selected.extend(ordered[:quotas[task]])
    return selected


def fixed_family_split(config, schemas):
    """Reserve whole source groups before sampling the development subset."""
    import copy
    import random

    settings = config['evaluation']
    count = settings['holdout_families_per_task']
    if type(count) is not int or count < 1:
        raise ValueError('Holdout family count must be a positive integer')
    full = copy.deepcopy(config)
    full['evaluation'].pop('total_examples', None)
    full['development_examples_per_task'] = 30
    rows = load_fixed_validation(full, schemas)
    rng = random.Random(settings.get('subset_seed', config['random_seed']))
    reserved = set()
    owners = {}
    for item in rows:
        group, task = item['source_group'], item['record']['task']
        if owners.setdefault(group, task) != task:
            raise ValueError('Fixed source group spans multiple tasks')
    for task in sorted(schemas):
        groups = sorted(group for group, owner in owners.items() if owner == task)
        if count >= len(groups):
            raise ValueError('Holdout must leave development families for each task')
        reserved.update(rng.sample(groups, count))
    development = [item for item in rows if item['source_group'] not in reserved]
    holdout = [item for item in rows if item['source_group'] in reserved]
    minimum = config['development_examples_per_task']
    total = settings.get('total_examples', minimum * len(schemas))
    return fixed_subset(development, schemas, total, minimum,
                        settings.get('subset_seed', config['random_seed'])), holdout
